-- ============================================================
-- SEED EXT 3: Módulo 04 — Present Continuous (ex 119-215)
-- Novos tópicos: stative vs dynamic avançado, PC em discurso
-- acadêmico, PC para arranjos futuros, TOEFL integrado
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'present-continuous';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo present-continuous não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 31: stative vs dynamic — casos avançados e difíceis
  (cid,31,119,'multiple_choice','What is the difference: "I think this is correct" vs "I''m thinking about changing my methodology"?','"Think" = stative (opinion/belief) in the first; dynamic (mental process, ongoing) in the second.','["They are identical","''Think'' = stative (opinion/belief) in the first; dynamic (mental process, ongoing) in the second.","Stative verbs can never use the continuous","The continuous is always incorrect with think"]','"Think" = stative when = believe/have opinion. Dynamic when = actively deliberating.','hard'),
  (cid,31,120,'gap_fill','The liquid _____ (taste) salty — we may have added too much sodium. (perception)','tastes',NULL,'"Taste" as stative (perception = this is how it tastes right now). Not tasting.','medium'),
  (cid,31,121,'gap_fill','The chef _____ (taste) the soup to check the seasoning. (active tasting = deliberate action)','is tasting',NULL,'"Taste" as dynamic verb (doing it deliberately) = present continuous.','medium'),
  (cid,31,122,'multiple_choice','Which sentence uses "see" correctly in both senses?','I see what you mean (stative = understand). I''m seeing the professor at 3 p.m. (dynamic = meeting).','["I''m seeing your point. I see the professor at 3 p.m. (both wrong).","I see what you mean (stative). I''m seeing the professor at 3 p.m. (dynamic = meeting).","I''m seeing what you mean. I see the professor at 3 p.m. (both wrong).","I see the professor at 3 p.m. (both uses the same form)."]','See = stative (perceive/understand) vs dynamic (meet/attend).','hard'),
  (cid,31,123,'gap_fill','She _____ (appear) tired — she may be ill. (seem = stative appearance)','appears',NULL,'"Appear" = stative when = seem. "She is appearing" = wrong in this context.','medium'),
  (cid,31,124,'multiple_choice','Which sentence uses a stative verb INCORRECTLY?','The patient is seeming much better after the treatment.','["The patient seems much better after the treatment (correct — stative).","The data suggest a significant correlation (correct — stative).","The results are looking promising (dynamic ''look'' for ongoing visual evaluation — acceptable in informal contexts).","The patient is seeming much better after the treatment."]','"Seeming" = wrong. "Seem" is a stative verb of appearance — no continuous.','hard'),

  -- BLOCK 32: PC com always/constantly/forever (irritação)
  (cid,32,125,'gap_fill','He _____ (always/leave) the lab equipment uncleaned for the next person to deal with!','is always leaving',NULL,'"Is always + -ing" = habitual action expressed with irritation or criticism.','medium'),
  (cid,32,126,'multiple_choice','What is the pragmatic effect of using "always" with present continuous?','It expresses the speaker''s irritation or criticism about a repeated habit.','["It makes the statement more formal","It expresses the speaker''s irritation or criticism about a repeated habit.","It is incorrect — always cannot modify continuous verbs","It emphasizes a positive quality"]','"Is always + -ing" = emotional coloring (usually negative: annoying habit).','medium'),
  (cid,32,127,'gap_fill','The government _____ (constantly/change) its position on this issue, making long-term planning impossible.','is constantly changing',NULL,'"Is constantly + -ing" = critical comment on unstable behavior.','medium'),
  (cid,32,128,'multiple_choice','Which pair correctly shows the contrast between neutral habit and irritated habit?','She always calls before visiting (neutral). She''s always calling at the worst possible moment (irritated).','["She is calling every day (neutral). She always calls every day (irritated).","She always calls before visiting (neutral). She''s always calling at the worst possible moment (irritated).","She always calls = irritated. She is always calling = neutral.","Both forms are identical in meaning."]','Present simple + always = neutral habit. PC + always = emotional/irritated habit.','hard'),

  -- BLOCK 33: PC para arranjos futuros definidos
  (cid,33,129,'gap_fill','She _____ (present) her doctoral research at the conference next month — the slot is already confirmed.','is presenting',NULL,'PC for definite, organized future plans (similar to "is going to present" but emphasizes arrangements already made).','medium'),
  (cid,33,130,'multiple_choice','Which sentence uses present continuous for a future arrangement MOST naturally?','The committee is reviewing the applications next week.','["The committee reviews the applications next week (present simple for schedule).","The committee is going to review the applications next week (prior plan).","The committee is reviewing the applications next week.","The committee will review the applications next week (will = less organized arrangement)."]','PC for future = personal arrangements already set in motion.','medium'),
  (cid,33,131,'gap_fill','They _____ (move) to the new laboratory facility in January — everything has been arranged with the facilities team.','are moving',NULL,'PC = future arrangement already organized and confirmed.','easy'),
  (cid,33,132,'multiple_choice','What is the difference between "The conference starts at 9" and "The conference is starting at 9"?','"Starts" = fixed schedule (timetable). "Is starting" = personal arrangement/emphasis on the imminent start.','["They are identical","''Starts'' = fixed schedule (timetable). ''Is starting'' = personal arrangement/emphasis on the imminent start.","Is starting is always incorrect for fixed events","Starts is more formal than is starting"]','Present simple = timetable. PC = personal arrangement or immediate start.','hard'),

  -- BLOCK 34: PC passivo (is being + past participle)
  (cid,34,133,'gap_fill','The new campus buildings _____ (construct/passive) and are expected to be ready by next autumn.','are being constructed',NULL,'"Are being + past participle" = present continuous passive (ongoing action).','hard'),
  (cid,34,134,'multiple_choice','Which sentence uses present continuous passive correctly?','The data are currently being processed by an independent analytics team.','["The data is currently being processing by an independent team.","The data currently processes by an independent analytics team.","The data are currently being processed by an independent analytics team.","The data are been processed by an independent analytics team."]','"Are being + past participle" = ongoing passive. "Are" for plural "data."','hard'),
  (cid,34,135,'gap_fill','Three new drugs _____ (test/passive) in clinical trials at the moment.','are being tested',NULL,'"Are being tested" = ongoing clinical process (present passive continuous).','medium'),
  (cid,34,136,'multiple_choice','In academic writing, "is being analyzed" (present continuous passive) expresses:','An ongoing process happening at or around the time of writing.','["A past action","An ongoing process happening at or around the time of writing.","A future plan","A habitual action"]','PC passive = ongoing process at the moment of speaking/writing.','easy'),

  -- BLOCK 35: TOEFL Reading
  (cid,35,137,'multiple_choice','[TOEFL Reading] "Researchers are increasingly recognizing the role of the gut microbiome in mental health." Why present continuous?','The recognition is an ongoing, evolving process — it is happening progressively.','["Recognizing is a stative verb","The text is about the future","The recognition is an ongoing, evolving process — it is happening progressively.","It is used for emphasis only"]','PC for gradual, ongoing change or development in academic writing.','medium'),
  (cid,35,138,'gap_fill','[TOEFL Reading] "The Arctic ice sheet _____ (melt) at an accelerating rate, according to satellite data collected over the past decade." Best form?','is melting',NULL,'"Is melting" = ongoing environmental process being documented.','easy'),
  (cid,35,139,'multiple_choice','[TOEFL Reading] "This study is contributing to our understanding of..." The present continuous "is contributing" suggests:','The study''s contribution is ongoing — relevant to the current moment.','["The study will contribute in the future","The study contributed in the past","The study''s contribution is ongoing — relevant to the current moment.","The continuous is used for politeness"]','PC in academic framing = currently having an effect.','medium'),
  (cid,35,140,'gap_fill','[TOEFL Reading] "The population of monarch butterflies _____ (decline/passive + progressive) as milkweed habitats are destroyed." Best passive form?','is being depleted / is declining',NULL,'"Is declining" = active ongoing; "is being depleted" = passive ongoing. Either appropriate.','hard'),

  -- BLOCK 36: TOEFL Speaking
  (cid,36,141,'production','[TOEFL Speaking — 45s] A reading says cities are changing rapidly due to technology. Discuss what is currently happening in cities and what is being planned. Use: PC (active), PC passive, PC for future arrangements.','',NULL,'Cities around the world are currently undergoing transformation driven by digital infrastructure and smart technology. New sensor networks are being installed across transportation systems, and energy grids are being redesigned to accommodate decentralized renewable sources. At the same time, urban planners are rethinking street design to prioritize cyclists and pedestrians over private cars. Next year, the city of Oslo is opening an entirely car-free city center, which represents one of the boldest urban experiments currently underway. While these changes are promising, questions of equity — who is benefiting and who is being left behind — are not being adequately addressed.','hard'),
  (cid,36,142,'production','[TOEFL Speaking — 45s] Your classmate is always submitting late work and blaming others. Give advice using PC with always/constantly for irritation, and contrast with present simple for neutral facts.','',NULL,'I notice that he is constantly submitting assignments late and is always blaming technical problems that seem suspiciously convenient. This pattern is becoming a serious issue — professors are starting to lose patience. The fact is, deadlines are clearly communicated at the start of each term. He is always making the same excuses instead of addressing the underlying problem, which appears to be poor time management. I would recommend he starts using a digital planner, as students who organize their time effectively consistently produce better work.','hard'),

  -- BLOCK 37: TOEFL Writing
  (cid,37,143,'production','[TOEFL Writing — 150 words] Write an academic paragraph on "Current trends in renewable energy." Use: PC (active for ongoing trends), PC passive (processes being done), PC for arranged future, present simple for facts, and stative verbs correctly (know, include, remain).','',NULL,'Renewable energy is currently transforming the global electricity sector at an unprecedented pace. Solar panel costs have fallen by over 90% since 2010, and installed capacity is growing rapidly across both developed and developing nations. Governments are investing heavily in grid modernization, and new offshore wind farms are being constructed along coastlines that previously lacked the infrastructure for large-scale generation. Scientists know that the transition will require significant storage solutions, and battery technology is rapidly improving to meet this challenge. Several major economies are planning to phase out coal-fired generation within the next decade — Germany, for instance, is shutting down its last coal plant in 2038. The evidence remains compelling: renewable sources are becoming not merely viable but essential to meeting climate commitments while sustaining economic growth.','hard'),
  (cid,37,144,'production','[TOEFL Writing — Error Correction] Fix present continuous errors: "She is knowing the answer already. The results are seeming positive so far. They currently build a new research center. The data is being currently collected by fieldworkers. He always leave the microscope on, which wastes electricity."','',NULL,'is knowing → knows (know = stative — no continuous); are seeming → seem (seem = stative); currently build → are currently building (PC for ongoing construction); is being currently → is currently being (adverb order: is currently being collected); always leave → is always leaving (PC + always for habitual irritating action).','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
